UPDATE repeated_questions
   SET baseline_askers = askers, updated_at = #{now}
 WHERE session_id = #{sessionId}
   AND dismissed_at IS NOT NULL
   AND baseline_askers IS NOT NULL
   AND askers < baseline_askers

UPDATE repeated_questions
   SET dismissed_at      = NULL,
       askers_at_dismiss = NULL,
       baseline_askers   = NULL,
       reexposed_at      = #{now},
       updated_at        = #{now}
 WHERE session_id = #{sessionId}
   AND dismissed_at IS NOT NULL
   AND baseline_askers IS NOT NULL
   AND askers - baseline_askers >= #{threshold}

UPDATE repeated_questions
   SET dismissed_at      = #{now},
       askers_at_dismiss = askers,
       baseline_askers   = NULL,
       updated_at        = #{now}
 WHERE session_id = #{sessionId}
   AND question_id = #{questionId}
   AND dismissed_at IS NULL

